"""Generated ZIP unit fixtures; these are never physical evaluation evidence."""
import io
import zipfile
import pytest
from scripts import acquire_industreal_candidate as candidate


def test_directory_rejects_generated_substitute():
    stream = io.BytesIO()
    with zipfile.ZipFile(stream, "w", zipfile.ZIP_DEFLATED) as archive:
        archive.writestr("unselected.txt", b"not a video")
        archive.writestr(candidate.VIDEO_NAME, b"generated parser fixture")
    raw = stream.getvalue()
    # The real-size guard must reject generated bytes even with the expected name.
    with pytest.raises(ValueError, match="Unexpected selected ZIP member"):
        candidate.selected_entry(raw, 0)
    with pytest.raises(ValueError, match="end directory missing"):
        candidate.selected_entry(b"not a ZIP", 0)


def test_observed_real_directory_selects_one_member():
    path = candidate.ROOT / "runtime/industreal_zip_tail.bin"
    if not path.exists():
        pytest.skip("Optional bounded directory receipt not present")
    raw = path.read_bytes()
    member = candidate.selected_entry(raw, candidate.ARCHIVE_SIZE - len(raw))
    assert member["name"] == "25_assy_0_1.mp4"
    assert member["size"] == 37_472_124
    assert member["compressed"] == 36_595_998
    assert member["crc32"] == 9_773_814


def test_selected_local_bytes_have_pinned_hashes():
    folder = candidate.ROOT / "data/external/industreal_candidate"
    if not (folder / candidate.VIDEO_NAME).exists():
        pytest.skip("External research assets not installed; no synthetic substitute")
    receipt = candidate.video(folder)
    model = candidate.model(folder)
    assert receipt["sha256"] == candidate.VIDEO_SHA256
    assert receipt["mirror_provenance"] == "UNVERIFIED_AGAINST_OFFICIAL_ARCHIVE"
    assert receipt["recording_split"] == "UNKNOWN_NOT_HELD_OUT"
    assert model["sha256"] == candidate.MODEL_SHA256
    assert "NOT original" in model["publisher"]
